architecture.h4_f:
msg = CBOR{v:1, text, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, текст, reply_to?, thread_id?, згадки?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad=hex(room_id))
дріт = CBOR{
  v: 1,
  зашифрований текст: hex(ct), // змінна довжина
  nonce: hex(12 B),
  sender_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
зовнішній = CBOR{
  джерело_вузол: hex32,
  target_user: int64,
  inner_ciphertext: байти,
  inner_nonce: байти,
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, зовнішній)
POST /federation/deliver { envelope: outer, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { ім'я користувача, пароль, x25519_public_key, display_name, phone?, email?, avatar_emoji }

Відповідь 201 Створено:
  { access_token, refresh_token, user_id, username, ...}

auth.h3_f:
access_token корисне навантаження:
  { sub: user_id, jti: device_id, typ: "access", exp: зараз + 15 хвилин }
корисне навантаження refresh_token:
  { sub: user_id, jti: device_id, typ: "оновити", exp: зараз + 30 днів }

HS256, підписаний 64-байтовим секретом вузла з .env

auth.h4_f:
register_begin(): виклик = rand(32)
                    options = { rp.id, user.id, pubKeyCredParams, challenge }
                    варіанти повернення

register_finish(атестація):
  перевірте атестацію на TPM / Secure Enclave root CA
  store { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → зареєстровано новий пристрій; JWT повернуто.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Розгорнутий кадр: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {назва файлу, розмір, chunk_size_hint}
            ← {upload_id, chunk_size}
chunk PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
завершити POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL на незавершеному: 24 год

files.h4_f:
deny_list = {
  "application/x-dosexec",
  "application/x-sharedlib",
  "application/x-mach-binary",
}
if magic.from_buffer(buf[:1024]) у deny_list: повертає 415

presence.h1_f:
клієнт: після першого натискання клавіші → відправити {type:"t", state:"start"}
         більше не надсилає протягом 3 с, якщо стан не зміниться
         10 с після останнього натискання клавіші → відправити {type:"t", state:"stop"}
приймач: автоматична зупинка через 10 с після останнього «старту», якщо «стоп» не надійшов

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS трансляція {type:"c", kind:"invite", call_id}
WS трансляція {type:"c", kind:"offer", sdp}
WS трансляція {type:"c", kind:"answer", sdp}
WS трансляція {type:"c", kind:"candidate",ice} × N
POST /api/calls/{call_id}/end

federation.h2_f:
конверт = {
  вихідний_вузол: hex32,
  target_user: int64,
  inner_ciphertext: байти,
  inner_nonce : байти,
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(конверт))
POST /federation/deliver { конверт, підпис }

gossip.h3_f:
advertisement = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(реклама))
корисне навантаження пліток: [..., {ad, sig}, ...]

отримувач: перевірити sig на ad.pubkey → зберегти, якщо добре
додатково: PoW з 2^18 початкових нулів на {pubkey, endpoint}

stealth.h2_f:
ClientHello bytes = chrome_120_template with {
  випадковий = наш випадковий,
  server_name = наше ім’я хоста (або ECH),
  session_id = ідентифікатор нашого сеансу,
}
JA4 = t13d_xxxx_xxxx_xxxx (відповідає поточній стабільній версії Chrome)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: домен(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(request) {decrypt(request.content.userInfo)}
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Веб SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
інструмент = sign_tool
input = вихідне дерево, ключі/release.key
manifest = {
  версія: "0.1.0",
  вбудовано: unix_ms,
  файли: [{шлях, sha256, розмір}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(маніфест))
вихід = INTEGRITY.sig.json = {маніфест, signed_by: pub_hex, sig: sig_hex}

bots.h1_f:
створити: POST /api/bots {ім’я користувача, відображуване_ім’я, код}
          → {bot_id, token, pubkey}
запуск: у процесі (співпрограма всередині вузла)
      OR зовнішній (long-poll /api/bots/{id}/updates, token-auth'd)
повідомлення: {текст, підпис: Ed25519-Sign(bot_priv, canonical_msg)}

