fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  вміст, -- токенований стовпець
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
запит: SELECT rowid FROM messages_fts WHERE content MATCH 'foo'

